<?php
require_once __DIR__ . '/includes/auth.php'; require_staff();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare('UPDATE feedback SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['id']]);flash('success','Feedback status updated.');redirect('feedback.php');}
$items=$pdo->query('SELECT f.*,r.barangay_id,u.full_name AS resident_name FROM feedback f LEFT JOIN residents r ON r.id=f.resident_id LEFT JOIN users u ON u.resident_id=f.resident_id ORDER BY f.created_at DESC')->fetchAll();$new=(int)$pdo->query("SELECT COUNT(*) FROM feedback WHERE status='New'")->fetchColumn();$pageTitle='Resident feedback';$activePage='feedback';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Community / Listening desk</div><h1>Resident feedback</h1><p>Review resident experiences and turn feedback into visible improvements.</p></div><span class="view-pill"><i></i> <?= $new ?> new</span></section><div class="stats-grid"><div class="stat-card"><div class="stat-icon violet">♡</div><span class="stat-label">Total feedback</span><strong><?= count($items) ?></strong><small>Resident submissions</small></div><div class="stat-card"><div class="stat-icon amber">!</div><span class="stat-label">Needs review</span><strong><?= $new ?></strong><small>New submissions</small></div><div class="stat-card"><div class="stat-icon mint">✓</div><span class="stat-label">Resolved</span><strong><?= count(array_filter($items,fn($i)=>$i['status']==='Resolved')) ?></strong><small>Closed responses</small></div></div><section class="panel table-panel"><div class="table-toolbar"><div><div class="eyebrow">Resident voice</div><h2>Feedback submissions</h2></div><span class="muted">Latest first</span></div><div class="feedback-list"><?php foreach($items as $item): ?><article class="feedback-card"><div class="feedback-quote">“</div><p><?= h($item['message']) ?></p><div class="feedback-author"><div class="avatar"><?= h(strtoupper(substr($item['resident_name']??'RS',0,2))) ?></div><div><strong><?= h($item['resident_name']??'Resident') ?></strong><span><?= h($item['category']) ?> · <?= h($item['rating']) ?>/5 · <?= h(date('M d, Y',strtotime($item['created_at']))) ?></span></div><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="id" value="<?= h($item['id']) ?>"><select name="status" onchange="this.form.submit()"><option <?= $item['status']==='New'?'selected':'' ?>>New</option><option <?= $item['status']==='Reviewed'?'selected':'' ?>>Reviewed</option><option <?= $item['status']==='Resolved'?'selected':'' ?>>Resolved</option></select></form></div></article><?php endforeach; ?><?php if(!$items): ?><p class="empty-state">No resident feedback yet.</p><?php endif; ?></div></section><?php require __DIR__.'/partials/footer.php'; ?>
